```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        use crate::aap::caps::state_rw;

        // Mark every considered item as seen in the 'seen' store. Record only the
        // ones that were not already present, so `recorded` is the count of items
        // newly recorded this run. u32 is non-negative, so `recorded >= 0` holds.
        let mut recorded: u32 = 0;
        for id in &published.considered {
            if state_rw::get(id).is_none() {
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

